muro__sess_res muro__sess_offered_init(void) {
  muro__sess_res out;
  muro__sess_res *res = &out;
  int fail = 0;
  int cap = 0;
  memset(res, 0, sizeof *res);
  res->status = MURO_SESS_OK;
  res->state.key = 7;

  res->state.at = 19;
  res->state.stuck = 0;
  (void)fail;
  (void)cap;
  if (res->state.stuck || res->state.at == 0) {
    res->state.stuck = 1;
    res->state.at = 0;
    res->state.key = 7;
  }
  res->step = muro__sess_label(res->state.key, res->state.at);
  muro__sess_fill(res);
  return out;
}

muro__sess_res muro__sess_offered_step(muro__sess_st st, int dir, const muro__sess_val *value) {
  muro__sess_res out;
  muro__sess_res *res = &out;
  const muro__sess_st *saved = &st;
  (void)dir;
  (void)value;
  memset(res, 0, sizeof *res);
  res->state = st;
  if (dir != MURO_SESS_SEND && dir != MURO_SESS_RECV) {
    res->status = MURO_SESS_UNEXPECTED;
    res->step = "examples/dual.muro:16 session offered: end";
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    res->done = st.key == 7 ? muro__sess_is_done(st.key, st.at, st.stuck) : 0;
    return out;
  }
  if (st.key != 7) {
    res->status = MURO_SESS_UNEXPECTED;
    res->step = "examples/dual.muro:16 session offered: end";
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    return out;
  }
  if (st.stuck) {
    res->status = MURO_SESS_UNEXPECTED;
    res->step = muro__sess_label(st.key, st.at);
    muro__sess_lit(res->expected, sizeof res->expected, "done");
    return out;
  }
  switch (st.at) {
    case 19: {
      {
        int arm = -1;
        if (value && value->tag == MURO_SESS_PICK && value->bit <= 1) arm = (int)value->bit;
        if (dir != MURO_SESS_RECV || arm < 0) {
          res->status = MURO_SESS_UNEXPECTED;
          res->state = *saved;
          res->step = "examples/dual.muro:16 session offered: first branch";
          muro__sess_exp_at(19, saved, res->expected, sizeof res->expected);
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else {
          int fail = 0;
          int cap = 0;
          if (arm == 0) {
            res->state.at = 20;
            res->state.stuck = 0;
          } else {
            res->state.at = 21;
            res->state.stuck = 0;
          }
          if (cap) {
            res->state = *saved;
            res->status = MURO_SESS_UNEXPECTED;
            res->step = "examples/dual.muro:16 session offered: first branch";
            muro__sess_lit(res->expected, sizeof res->expected, "nat_at_most 100000");
            res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
          } else if (fail) {
            muro__sess_exp_at(19, saved, res->expected, sizeof res->expected);
            res->state = *saved;
            res->status = MURO_SESS_UNEXPECTED;
            res->step = "examples/dual.muro:16 session offered: first branch";
            res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
          } else {
            res->status = MURO_SESS_OK;
            res->step = "examples/dual.muro:16 session offered: first branch";
            muro__sess_fill(res);
          }
        }
      }
      break;
    }
    case 20: {
      res->status = MURO_SESS_UNEXPECTED;
      res->state = *saved;
      res->step = "examples/dual.muro:16 session offered: end";
      muro__sess_lit(res->expected, sizeof res->expected, "done");
      res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
      break;
    }
    case 21: {
      if (dir != MURO_SESS_RECV || !muro__sess_pay_6(value, saved)) {
        res->status = MURO_SESS_UNEXPECTED;
        res->state = *saved;
        res->step = "examples/dual.muro:16 session offered: first recv Nat";
        muro__sess_exp_at(21, saved, res->expected, sizeof res->expected);
        res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
      } else {
        int fail = 0;
        int cap = 0;

        res->state.at = 20;
        res->state.stuck = 0;
        if (cap) {
          res->state = *saved;
          res->status = MURO_SESS_UNEXPECTED;
          res->step = "examples/dual.muro:16 session offered: first recv Nat";
          muro__sess_lit(res->expected, sizeof res->expected, "nat_at_most 100000");
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else if (fail) {
          muro__sess_exp_at(21, saved, res->expected, sizeof res->expected);
          res->state = *saved;
          res->status = MURO_SESS_UNEXPECTED;
          res->step = "examples/dual.muro:16 session offered: first recv Nat";
          res->done = muro__sess_is_done(saved->key, saved->at, saved->stuck);
        } else {
          res->status = MURO_SESS_OK;
          res->step = "examples/dual.muro:16 session offered: first recv Nat";
          muro__sess_fill(res);
        }
      }
      break;
    }
    default:
      res->status = MURO_SESS_UNEXPECTED;
      res->step = "examples/dual.muro:16 session offered: end";
      muro__sess_lit(res->expected, sizeof res->expected, "done");
      break;
  }
  return out;
}

